use std::collections::{HashMap,VecDeque};use std::sync::Mutex;use score_engine::{Decision,IntelligenceSnapshot};
const DEFAULT_HISTORY_LIMIT:usize=200;
#[derive(Debug,Clone,PartialEq)]pub struct DecisionRecord{pub symbol:String,pub timestamp:i64,pub decision:Decision,pub score:f64,pub confidence:f64,pub risk:f64,pub data_quality:f64,pub agreement:f64,pub reasons:Vec<String>,pub warnings:Vec<String>}
impl From<&IntelligenceSnapshot> for DecisionRecord{fn from(s:&IntelligenceSnapshot)->Self{Self{symbol:s.symbol.clone(),timestamp:s.timestamp,decision:s.decision.decision,score:s.score,confidence:s.decision.confidence,risk:s.decision.risk,data_quality:s.data_quality,agreement:s.agreement,reasons:s.explanation.reasons.clone(),warnings:s.explanation.warnings.clone()}}}
pub struct DecisionHistory{records:Mutex<HashMap<String,VecDeque<DecisionRecord>>>,limit:usize}
impl Default for DecisionHistory{fn default()->Self{Self::new(DEFAULT_HISTORY_LIMIT)}}
impl DecisionHistory{pub fn new(limit:usize)->Self{Self{records:Mutex::new(HashMap::new()),limit:limit.max(1)}}pub fn push(&self,snapshot:&IntelligenceSnapshot){let mut all=self.records.lock().expect("decision history lock poisoned");let records=all.entry(snapshot.symbol.clone()).or_default();records.push_back(DecisionRecord::from(snapshot));while records.len()>self.limit{records.pop_front();}}pub fn latest(&self,symbol:&str,limit:usize)->Vec<DecisionRecord>{let all=self.records.lock().expect("decision history lock poisoned");all.get(symbol).map(|records|records.iter().rev().take(limit).cloned().collect()).unwrap_or_default()}}
#[cfg(test)]mod tests{use super::*;use score_engine::{Explanation,MetaDecision,SignalComponents};fn snapshot(ts:i64)->IntelligenceSnapshot{IntelligenceSnapshot{symbol:"BTCUSDT".into(),timestamp:ts,score:75.0,components:SignalComponents{volume_anomaly:75.0,funding_extreme:50.0,order_book_imbalance:60.0,rsi_divergence:65.0},derivatives_score:Some(70.0),data_quality:85.0,agreement:95.0,decision:MetaDecision{decision:Decision::Long,signal_quality:80.0,confidence:80.0,risk:20.0},explanation:Explanation{headline:"Long setup".into(),reasons:vec!["score".into()],warnings:vec![]}}}#[test]fn keeps_bounded_history(){let h=DecisionHistory::new(2);h.push(&snapshot(1));h.push(&snapshot(2));h.push(&snapshot(3));let r=h.latest("BTCUSDT",10);assert_eq!(r.len(),2);assert_eq!(r[0].timestamp,3);assert_eq!(r[1].timestamp,2);}}
